    static Object temporal()throws Exception{
        crawl(a);done(a);var raw=row("SELECT CAST(started_at AS CHAR) s,CAST(completed_at AS CHAR) e FROM schedule_crawl_run ORDER BY crawl_run_id DESC LIMIT 1");
        long collectedId=n("SELECT MIN(event_id) FROM calendar_event");String collectedRaw=row("SELECT CAST(collected_at AS CHAR) t FROM calendar_event WHERE event_id=?",collectedId).get("t").toString();
        for(int port:List.of(8081,8082)){var s=status(port);check(LocalDateTime.parse(s.path("lastRunAt").asString()).equals(LocalDateTime.parse(raw.get("s").toString().replace(' ','T')))&&LocalDateTime.parse(s.path("lastCompletedAt").asString()).equals(LocalDateTime.parse(raw.get("e").toString().replace(' ','T'))),"Raw history and HTTP shifted");
            var detail=api(port,"GET","/api/admin/crawled-schedules/"+collectedId,null,admin.token);expect(detail,200,"");check(LocalDateTime.parse(detail.data().path("collectedAt").asString()).equals(LocalDateTime.parse(collectedRaw.replace(' ','T'))),"Raw collected DATETIME and admin HTTP shifted");
        }
        var now=LocalDateTime.now(ZoneId.of("Asia/Seoul"));check(Duration.between(LocalDateTime.parse(raw.get("s").toString().replace(' ','T')),now).abs().toSeconds()<30,"History is not Seoul wall time");
        check(n("SELECT COUNT(*) FROM calendar_event WHERE collected_at IS NULL")==0,"Collected time missing");expect(create(8082,me,personal,"midnight"),200,"");boolean found=false;
        for(var x:list(8081,me))if(x.path("title").asString().equals("midnight")){found=true;check(x.path("startTime").asString().equals("23:59")&&x.path("endTime").asString().equals("00:00"),"Cross JVM midnight time shifted");}check(found,"Midnight event missing");
        // Keep the boundary later than the just-generated run so latest-by-time remains deterministic next year too.
        LocalDateTime boundary=LocalDate.now(ZoneId.of("Asia/Seoul")).plusDays(1).atTime(23,59,59);
        update("INSERT INTO schedule_crawl_run(category,status,collected_count,started_at,completed_at) VALUES('SCHOOL','COMPLETED',0,?,?)",boundary,boundary.plusSeconds(1));
        for(int port:List.of(8081,8082)){var s=status(port);check(LocalDateTime.parse(s.path("lastRunAt").asString()).equals(boundary)&&LocalDateTime.parse(s.path("lastCompletedAt").asString()).equals(boundary.plusSeconds(1)),"History midnight changed across HTTP servers");}
        return Map.of("jvmA","Asia/Seoul","jvmB","UTC","jdbcA","UTC","jdbcB","Asia/Seoul","rawAndHttpEqual",true,"historyMidnight",true);
    }
