    static Map<String,String> ddl(Connection c)throws Exception{var m=new TreeMap<String,String>();for(String t:tables)m.put(t,rows(c,"SHOW CREATE TABLE `"+t+"`").getFirst().values().stream().skip(1).findFirst().orElseThrow().toString().replaceAll(" AUTO_INCREMENT=\\d+",""));return m;}
    static void cleanup()throws Exception{if(tables==null)return;try(var c=open()){check(number(c,"SELECT COUNT(*) FROM information_schema.processlist WHERE USER=? AND DB=?",account(),db())==1,"Server connections remain after JVM termination");var fks=rows(c,"SELECT table_name child,referenced_table_name parent FROM information_schema.key_column_usage WHERE table_schema=DATABASE() AND referenced_table_name IS NOT NULL");var remaining=new HashSet<>(tables);while(!remaining.isEmpty()){var leaves=remaining.stream().filter(t->fks.stream().noneMatch(f->remaining.contains(f.get("child").toString())&&f.get("parent").equals(t)&&!f.get("child").equals(t))).sorted().toList();check(!leaves.isEmpty(),"FK cleanup cycle");for(var t:leaves){exec(c,"DELETE FROM `"+t+"`");remaining.remove(t);}}for(var t:tables)check(number(c,"SELECT COUNT(*) FROM `"+t+"`")==0,"Fixture rows remain");check(originalDdl.equals(ddl(c)),"Schema changed during tests");write(out.resolve("cleanup.json"),Map.of("tables",tables.size(),"allEmpty",true,"ddlUnchanged",true,"serverConnectionsRemaining",0));}}
    static Map<String,String> protectedHashes()throws Exception{var m=new TreeMap<String,String>();for(String directory:List.of("backend/src","frontend/src","backend/tools/auth-mysql-concurrency","backend/tools/auth-mysql-multi-instance","backend/tools/user-mysql-concurrency","backend/tools/user-mysql-multi-instance","backend/tools/calendar-mysql-concurrency","backend/migrations"))try(var files=Files.walk(root.resolve(directory))){for(var f:files.filter(Files::isRegularFile).toList())m.put(root.relativize(f).toString(),HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(f))));}for(var name:List.of("AGENTS.md","backend/agent.md","backend/API.md","backend/ERD.md","backend/DEPLOYMENT.md"))m.put(name,HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(root.resolve(name)))));return m;}
